/* ==========================================================================
   PARTE 2 — MARCA E ILUSTRAÇÕES
   Mesma técnica do protótipo em React, portada para funções que devolvem
   strings de SVG. A tocha é a única assinatura visual (ver Tocha.tsx); as
   silhuetas em oração seguem as duas restrições descobertas construindo o
   protótipo: o tronco é um path preenchido com cintura e pernas separadas
   (como traço grosso, virava pino de boliche), e uma silhueta de frente não
   mostra mãos unidas ao peito — por isso o repertório de poses se limita ao
   que a silhueta resolve bem.
   ========================================================================== */

function svgLogo(inverida){
  return `<img src="${LOGO_B64}" width="42" height="42" alt="" style="width:2.625rem;height:2.625rem;object-fit:contain;border-radius:99px;flex-shrink:0" />`;
}

function svgLogoComTexto(inverida){
  const corTitulo = inverida ? '#fff' : 'var(--fg)';
  const corSub = inverida ? 'rgba(255,255,255,.72)' : 'var(--accent)';
  return `${svgLogo(inverida)}<span class="logo-txt"><b style="color:${corTitulo}">MEPB</b><span style="color:${corSub}">Missão Evangélica<br>Pentecostal do Brasil</span></span>`;
}

/** Tocha institucional — assinatura visual única do portal, usada em marca d'água. */
function svgTocha(opacidade){
  return `<svg viewBox="0 0 120 220" aria-hidden="true" focusable="false" style="opacity:${opacidade}">
    <path d="M60 4c-2 16-9 24-17 33-7.5 8.5-11 16.5-11 24.5C32 76 44 86 60 86s28-10 28-24.5c0-6.5-2.5-12.5-7.5-18-3 3.5-6.5 5-10 4 6-11 3.5-24-10.5-44Z" fill="currentColor"/>
    <path d="M60 34c-1.5 9-5 13.5-9 18.5-3.5 4.5-5 8.5-5 12.5 0 7.5 6 13 14 13s14-5.5 14-13c0-6.5-4.5-12-14-31Z" fill="currentColor" opacity=".5"/>
    <path d="M43 90h34l-4.5 13h-25L43 90Z" fill="currentColor"/>
    <path d="M52.5 103h15l-2 94h-11l-2-94Z" fill="currentColor" opacity=".85"/>
    <path d="M45 197h30l3 13H42l3-13Z" fill="currentColor"/>
  </svg>`;
}

/* Silhueta de figura em oração/adoração — três poses que a silhueta de frente
   consegue expressar sem que os braços se percam sobre o tronco. */
const CORPO_FRENTE = "M40 17 C36.5 18.5 35.5 20.5 35.5 23 L37 44 L38.5 52 L37 74 L36 96 C35.6 98 36.6 99 38.5 99 L43 99 C44.6 99 45.2 98 45.2 96 L45.8 74 L50 59 L54.2 74 L54.8 96 C54.8 98 55.4 99 57 99 L61.5 99 C63.4 99 64.4 98 64 96 L63 74 L61.5 52 L63 44 L64.5 23 C64.5 20.5 63.5 18.5 60 17 Z";
const TRACO_ATTR = 'fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="5.6"';

function svgFigura(pose){
  const cabecaBaixa = pose === 'cabeca-baixa';
  const cx = cabecaBaixa ? 51.5 : 50, cy = cabecaBaixa ? 11.5 : 9;
  let bracos = '';
  if (pose === 'maos-erguidas') bracos = `<path d="M37 24 L31 12 L30.5 4M63 24 L69 12 L69.5 4" ${TRACO_ATTR}/>`;
  else if (pose === 'bracos-abertos') bracos = `<path d="M37 25 L27 31 L20 26M63 25 L73 31 L80 26" ${TRACO_ATTR}/>`;
  else bracos = `<path d="M37 26 L33 40 L34 54M63 26 L67 40 L66 54" ${TRACO_ATTR}/>`;
  return `<g><ellipse cx="${cx}" cy="${cy}" rx="6" ry="7" fill="currentColor"/><path d="${CORPO_FRENTE}" fill="currentColor"/>${bracos}</g>`;
}

/** Congregação em adoração, contra a luz — mesma composição do CongregacaoEmOracao.tsx. */
function svgCongregacao(claro, idSufixo){
  const fundo = [
    {x:40,e:.74,p:'cabeca-baixa'},{x:138,e:.78,p:'maos-erguidas'},{x:244,e:.72,p:'cabeca-baixa'},
    {x:348,e:.77,p:'bracos-abertos'},{x:448,e:.73,p:'maos-erguidas'},{x:544,e:.76,p:'cabeca-baixa'},
  ];
  const frente = [
    {x:-8,e:1.02,p:'cabeca-baixa'},{x:94,e:1.1,p:'maos-erguidas'},{x:200,e:1,p:'cabeca-baixa'},
    {x:306,e:1.12,p:'bracos-abertos'},{x:424,e:1.02,p:'maos-erguidas'},{x:528,e:1.06,p:'cabeca-baixa'},
  ];
  const tinta = claro ? '#ffffff' : 'var(--navy-900)';
  const corLuz = claro ? '#ffffff' : 'var(--gold-300)';
  const id = 'cong-' + idSufixo;
  const grupoFundo = fundo.map(f => `<g transform="translate(${f.x} ${212-100*f.e}) scale(${f.e})">${svgFigura(f.p)}</g>`).join('');
  const grupoFrente = frente.map(f => `<g transform="translate(${f.x} ${272-100*f.e}) scale(${f.e})">${svgFigura(f.p)}</g>`).join('');
  return `<svg viewBox="0 0 640 280" role="img" aria-label="Ilustração: congregação reunida em oração e adoração, sob um feixe de luz." style="width:100%;height:auto">
    <defs>
      <radialGradient id="luz-${id}" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="${corLuz}" stop-opacity="${claro?0.3:0.4}"/>
        <stop offset="55%" stop-color="${corLuz}" stop-opacity="${claro?0.09:0.13}"/>
        <stop offset="100%" stop-color="${corLuz}" stop-opacity="0"/>
      </radialGradient>
      <linearGradient id="fade-${id}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#fff" stop-opacity="1"/>
        <stop offset="74%" stop-color="#fff" stop-opacity="1"/>
        <stop offset="100%" stop-color="#fff" stop-opacity="0"/>
      </linearGradient>
      <mask id="mask-${id}"><rect width="640" height="280" fill="url(#fade-${id})"/></mask>
    </defs>
    <ellipse cx="320" cy="20" rx="318" ry="250" fill="url(#luz-${id})"/>
    <g mask="url(#mask-${id})" color="${tinta}">
      <g opacity=".38">${grupoFundo}</g>
      <g opacity=".94">${grupoFrente}</g>
    </g>
  </svg>`;
}
/* ==========================================================================
   PARTE 3 — MAPA INTERATIVO
   Porta do MapaBrasil.tsx para JS puro: os mesmos 27 contornos geográficos
   reais, com hover, foco por teclado, clique e tooltip — usando transições
   CSS em vez de Framer Motion (aqui não há React para justificar a lib).
   ========================================================================== */

/**
 * Constrói o mapa dentro de `container` e devolve uma API para o chamador
 * consultar/mudar a seleção.
 *
 *   opts.contagemPorUF   {uf: número de igrejas}
 *   opts.aoSelecionar    (uf|"") => void — chamado ao clicar num estado ativo
 *   opts.selecionavel    se falso, o mapa é só visual (usado na prévia da home)
 */
function construirMapaBrasil(container, opts){
  opts = opts || {};
  const contagem = opts.contagemPorUF || {};
  const selecionavel = opts.selecionavel !== false;
  let ufSelecionada = opts.ufInicial || '';
  let ufSobre = null;

  const wrap = document.createElement('div');
  wrap.style.position = 'relative';

  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', `0 0 ${MAPA_VB.w} ${MAPA_VB.h}`);
  svg.setAttribute('role', 'group');
  svg.setAttribute('aria-label', 'Mapa do Brasil. Selecione um estado para ver as igrejas cadastradas.');
  svg.style.width = '100%';
  svg.style.height = 'auto';
  svg.style.overflow = 'visible';

  const tooltip = document.createElement('div');
  tooltip.className = 'mapa-tooltip';
  tooltip.setAttribute('aria-hidden', 'true');

  const caminhos = {};

  Object.keys(CONTORNOS).forEach(function(uf){
    const info = CONTORNOS[uf];
    const ativa = UFS_ATIVAS.indexOf(uf) !== -1;
    const path = document.createElementNS(ns, 'path');
    path.setAttribute('d', info.d);
    path.setAttribute('class', 'uf-path' + (ativa ? ' ativa' : ''));
    path.style.transformOrigin = info.c[0] + 'px ' + info.c[1] + 'px';
    path.style.transformBox = 'view-box';
    if (ativa && selecionavel){
      path.setAttribute('tabindex', '0');
      path.setAttribute('role', 'button');
      path.style.cursor = 'pointer';
    }
    const qtd = contagem[uf] || 0;
    const rotulo = ativa
      ? (NOMES_UF[uf] + ': ' + qtd + (qtd === 1 ? ' igreja' : ' igrejas'))
      : (NOMES_UF[uf] + ': sem igreja cadastrada');
    path.setAttribute('aria-label', rotulo);
    const title = document.createElementNS(ns, 'title');
    title.textContent = rotulo;
    path.appendChild(title);

    if (ativa){
      path.addEventListener('mouseenter', function(){ destacar(uf); });
      path.addEventListener('mouseleave', function(){ destacar(null); });
      if (selecionavel){
        path.addEventListener('focus', function(){ destacar(uf); });
        path.addEventListener('blur', function(){ destacar(null); });
        path.addEventListener('click', function(){ selecionar(uf); });
        path.addEventListener('keydown', function(e){
          if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); selecionar(uf); }
        });
      }
    }

    svg.appendChild(path);
    caminhos[uf] = path;
  });

  // Siglas sobre os estados ativos
  const siglas = {};
  UFS_ATIVAS.forEach(function(uf){
    const info = CONTORNOS[uf];
    const text = document.createElementNS(ns, 'text');
    text.setAttribute('x', info.c[0]);
    text.setAttribute('y', info.c[1]);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('dominant-baseline', 'central');
    text.setAttribute('class', 'uf-sigla');
    text.textContent = uf;
    svg.appendChild(text);
    siglas[uf] = text;
  });

  function atualizarVisual(){
    Object.keys(caminhos).forEach(function(uf){
      const path = caminhos[uf];
      const ativa = UFS_ATIVAS.indexOf(uf) !== -1;
      const sel = uf === ufSelecionada;
      const foco = uf === (ufSobre || ufSelecionada);
      path.classList.toggle('selecionada', sel);
      path.classList.toggle('foco', ativa && foco);
      if (siglas[uf]) siglas[uf].classList.toggle('foco', foco);
    });

    const destacada = ufSobre || ufSelecionada || null;
    if (destacada && UFS_ATIVAS.indexOf(destacada) !== -1){
      const info = CONTORNOS[destacada];
      const qtd = contagem[destacada] || 0;
      tooltip.innerHTML = '<p style="margin:0;font-weight:700;color:#fff;font-size:.875rem;white-space:nowrap">' + NOMES_UF[destacada] + '</p>' +
        '<p style="margin:.15rem 0 0;font-size:.75rem;color:rgb(255 255 255/.7);white-space:nowrap">' + qtd + (qtd === 1 ? ' igreja cadastrada' : ' igrejas cadastradas') + '</p>';
      tooltip.style.left = (info.c[0] / MAPA_VB.w * 100) + '%';
      tooltip.style.top = (info.c[1] / MAPA_VB.h * 100 - 3) + '%';
      tooltip.style.opacity = '1';
      tooltip.style.transform = 'translate(-50%,-100%) scale(1)';
    } else {
      tooltip.style.opacity = '0';
      tooltip.style.transform = 'translate(-50%,-100%) scale(.96)';
    }
  }

  function destacar(uf){ ufSobre = uf; atualizarVisual(); }

  function selecionar(uf){
    ufSelecionada = (ufSelecionada === uf) ? '' : uf;
    atualizarVisual();
    if (typeof opts.aoSelecionar === 'function') opts.aoSelecionar(ufSelecionada);
  }

  wrap.appendChild(svg);
  wrap.appendChild(tooltip);
  container.appendChild(wrap);
  atualizarVisual();

  return {
    definirSelecao: function(uf){ ufSelecionada = uf || ''; atualizarVisual(); },
    obterSelecao: function(){ return ufSelecionada; },
  };
}
