function iniciais(nome){
  const partes = nome.replace(/^(Pr\.|Pra\.|Missionário)\s+/, '').split(' ').filter(function(p){ return p.length>2; });
  return ((partes[0]||'')[0]||'') + ((partes[partes.length-1]||'')[0]||'');
}

/* Link de retorno ao início, repetido no alto de cada página dedicada
   (Missões, TV MEPB, Biblioteca, Localizador) — wayfinding previsível é
   prioridade alta no checklist de navegação: a pessoa sempre sabe onde
   está e como voltar, sem depender do botão "voltar" do navegador. */
function paginaVoltarHTML(clara){
  const cor = clara ? 'var(--fg-muted)' : 'rgb(255 255 255/.72)';
  const corHover = clara ? 'var(--fg)' : '#fff';
  return `<div class="container" style="padding-top:1.35rem">
    <a href="index.html" class="pagina-voltar-link" style="display:inline-flex;align-items:center;gap:.4rem;min-height:2.75rem;font-size:.8125rem;font-weight:600;color:${cor}">
      <svg viewBox="0 0 24 24" style="width:1rem;height:1rem" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 6l-6 6 6 6"/></svg>
      Início
    </a>
  </div>
  <style>.pagina-voltar-link:hover{color:${corHover}}</style>`;
}

/* Placeholder de imagem determinístico — mesma ideia do ImagemDemo.tsx: sem
   banco de imagens, gera um gradiente estável a partir do texto da legenda. */
function hashTexto(t){ let h=0; for (let i=0;i<t.length;i++){ h=(h<<5)-h+t.charCodeAt(i); h|=0; } return Math.abs(h); }
const PALETAS_IMG = [['#182050','#2e5c99'],['#232a5c','#414a85'],['#27507f','#4a85c8'],['#1e4232','#2f7d5a'],['#741921','#c8202f'],['#0d1129','#343a6c']];
function svgImagemDemo(semente, alt){
  const h = hashTexto(semente);
  const par = PALETAS_IMG[h % PALETAS_IMG.length];
  const rot = h % 40;
  const id = 'img'+h;
  return `<svg viewBox="0 0 320 180" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${alt}" style="width:100%;height:100%;display:block">
    <defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1" gradientTransform="rotate(${rot} .5 .5)">
      <stop offset="0%" stop-color="${par[0]}"/><stop offset="100%" stop-color="${par[1]}"/>
    </linearGradient></defs>
    <rect width="320" height="180" fill="url(#${id})"/>
    <g fill="none" stroke="#fff" stroke-opacity=".09"><circle cx="${40+(h%240)}" cy="${30+(h%120)}" r="70"/><circle cx="${40+(h%240)}" cy="${30+(h%120)}" r="110"/></g>
  </svg>`;
}
function fig169(semente, alt){
  return `<div style="aspect-ratio:16/9;border-radius:var(--radius-lg) var(--radius-lg) 0 0;overflow:hidden;background:var(--bg-muted)">${svgImagemDemo(semente,alt)}</div>`;
}

