/* ---------------------------------------------------------------- Missões */
/* Bandeiras em CSS puro (faixas de cor aproximadas) — evita depender de
   fontes de emoji, que renderizam de forma inconsistente entre celulares.
   É um "selo" de cor, não o brasão oficial completo. */
const CORES_BANDEIRA = {
  'Portugal': {tipo:'vertical', cores:['#046A38','#DA291C']},
  'Angola': {tipo:'horizontal', cores:['#CC092F','#000000']},
  'Moçambique': {tipo:'horizontal', cores:['#009739','#FCD116','#000000','#FCD116','#CE1126']},
  'Guiné-Bissau': {tipo:'horizontal', cores:['#FCD116','#009E49']},
  'Paraguai': {tipo:'horizontal', cores:['#D52B1E','#FFFFFF','#0038A8']},
  'Estados Unidos': {tipo:'horizontal', cores:['#B22234','#FFFFFF','#3C3B6E']},
  'Japão': {tipo:'sol', cores:['#FFFFFF','#BC002D']},
  'Amazônia ribeirinha': {tipo:'horizontal', cores:['#009739','#FEDD00','#012169']},
};
function bandeiraHTML(pais){
  const b = CORES_BANDEIRA[pais];
  if (!b) return '';
  let fundo;
  if (b.tipo === 'sol') fundo = `${b.cores[0]}`;
  else if (b.tipo === 'vertical') fundo = `linear-gradient(90deg, ${b.cores.join(',')})`;
  else fundo = `linear-gradient(0deg, ${b.cores.join(',')})`;
  const sol = b.tipo === 'sol' ? `<span style="position:absolute;inset:0;margin:auto;width:45%;height:45%;border-radius:99px;background:${b.cores[1]}"></span>` : '';
  return `<span aria-hidden="true" style="position:relative;display:inline-block;width:1.35rem;height:.95rem;border-radius:.2rem;overflow:hidden;background:${fundo};box-shadow:0 0 0 1px rgb(255 255 255/.35);vertical-align:middle;flex-shrink:0">${sol}</span>`;
}

