function iconeArquivo(tipo){
  return tipo === 'ZIP'
    ? '<svg viewBox="0 0 24 24" style="width:1.4rem;height:1.4rem" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M7 3.5h7l4 4V19a1.5 1.5 0 0 1-1.5 1.5h-9A1.5 1.5 0 0 1 6 19V5A1.5 1.5 0 0 1 7 3.5Z"/><path d="M11 4v2M13 7v2M11 10v2M13 13v2"/></svg>'
    : ICONES.file.replace('class="icon"','style="width:1.4rem;height:1.4rem"');
}
function secaoBiblioteca(){
  return `<section class="section-y soft-band" id="biblioteca" style="background:var(--bg-subtle)">
    ${paginaVoltarHTML(true)}
    <div class="container">
      <div class="reveal" style="text-align:center;max-width:34rem;margin-inline:auto">
        <p class="badge badge-primario">Biblioteca</p>
        <h2 class="rule rule-center" style="font-size:clamp(1.5rem,1.2rem + 1.3vw,2rem);margin-top:.75rem">Repositório de documentos oficiais</h2>
        <p style="margin-top:.75rem;color:var(--fg-muted)">Estatuto, regimento, manuais, hinário e materiais gráficos — tudo em um só lugar.</p>
      </div>
      <div class="reveal" style="margin-top:2.5rem;display:flex;gap:.75rem;align-items:center;background:var(--surface);border:1px solid var(--border-strong);border-radius:var(--radius-md);padding:0 1rem;max-width:30rem;margin-inline:auto">
        <span style="color:var(--fg-subtle)">${ICONES.search}</span>
        <input id="buscaDoc" type="search" class="field" style="border:none;padding-left:0" placeholder="Buscar documento...">
      </div>
      <div class="reveal" style="margin-top:1.75rem;display:flex;flex-wrap:wrap;gap:.6rem;justify-content:center" id="docTabs">
        ${DOC_CATEGORIAS.map(function(c,i){ return `<button type="button" class="doc-tab btn ${i===0?'btn-primary':'btn-outline'}" data-cat="${c}" style="min-height:2.35rem;padding:0 1rem;font-size:.8125rem">${c}</button>`; }).join('')}
      </div>
      <ul id="docGrid" style="list-style:none;margin:2.5rem 0 0;padding:0;display:grid;gap:1.1rem;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr))"></ul>
      <p id="docVazio" style="display:none;text-align:center;padding:3rem 1rem;color:var(--fg-muted)">Nenhum documento encontrado para essa busca.</p>
    </div>
  </section>`;
}
function cartaoDocumento(d){
  return `<li class="reveal">
    <div class="card hoverable" style="height:100%">
      <div class="card-body" style="display:flex;gap:1rem;align-items:flex-start">
        <span style="flex-shrink:0;display:inline-flex;width:2.75rem;height:2.75rem;align-items:center;justify-content:center;border-radius:var(--radius-md);background:${d.tipo==='ZIP'?'var(--support-subtle)':'var(--primary-subtle)'};color:${d.tipo==='ZIP'?'var(--support)':'var(--primary)'}">${iconeArquivo(d.tipo)}</span>
        <div style="min-width:0;flex:1">
          <div style="display:flex;gap:.4rem;flex-wrap:wrap"><span class="badge badge-neutro">${d.cat}</span><span class="badge badge-neutro">${d.tipo} · ${d.tam}</span></div>
          <h3 style="margin-top:.6rem;font-size:.9375rem;line-height:1.35">${d.n}</h3>
          <p style="margin-top:.35rem;font-size:.8125rem;color:var(--fg-muted)">${d.desc}</p>
          <button type="button" class="btn btn-outline" data-toast="Simulador local: download de demonstração — ${d.n}" style="margin-top:1rem;min-height:2.35rem;padding:0 1rem;font-size:.8125rem">${ICONES.download} Baixar</button>
        </div>
      </div>
    </div>
  </li>`;
}

