const ROTULO_TIPO_IGREJA = {'Sede Nacional':'Sede Nacional','Sede Estadual':'Sede Estadual','Igreja':'Igreja','Congregação':'Congregação'};

function normalizar(s){ return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(); }
function contemTexto(termo, campos){
  if (!termo.trim()) return true;
  const alvo = normalizar(termo);
  return campos.some(function(c){ return c && normalizar(c).indexOf(alvo) !== -1; });
}

function cartaoIgreja(ig){
  return `<div class="card hoverable"><div class="card-body">
    <div style="display:flex;justify-content:space-between;gap:.75rem;flex-wrap:wrap">
      <span class="badge ${ig.tipo==='Sede Nacional'?'badge-primario':'badge-neutro'}">${ROTULO_TIPO_IGREJA[ig.tipo]}</span>
      <span style="font-size:.875rem;font-weight:600;color:var(--fg-muted)">${ig.cidade}/${ig.uf}</span>
    </div>
    <h3 style="margin-top:.75rem;font-size:1.0625rem;line-height:1.3">${ig.nome}</h3>
    <ul style="list-style:none;margin:1rem 0 0;padding:0;display:flex;flex-direction:column;gap:.5rem;font-size:.875rem;color:var(--fg-muted)">
      <li style="display:flex;gap:.5rem"><span style="flex-shrink:0;margin-top:.15rem">${ICONES.pin}</span><span>${ig.endereco} — ${ig.bairro}</span></li>
      <li style="display:flex;gap:.5rem"><span style="flex-shrink:0;margin-top:.15rem">${ICONES.user}</span><span>${ig.pastor}</span></li>
      <li style="display:flex;gap:.5rem"><span style="flex-shrink:0;margin-top:.15rem">${ICONES.clock}</span><span>${ig.culto}</span></li>
    </ul>
  </div></div>`;
}

