/* ---------------------------------------------------------------- Tema */
(function initTema(){
  let salvo = null;
  try { salvo = localStorage.getItem('mepb-tema'); } catch(e){}
  const prefereEscuro = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  const tema = salvo || (prefereEscuro ? 'dark' : 'light');
  document.documentElement.setAttribute('data-theme', tema);
})();

function iconeTema(tema){
  return tema === 'dark'
    ? '<svg class="icon" viewBox="0 0 24 24"><circle cx="12" cy="12" r="4.5"/><path d="M12 2.5v2M12 19.5v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M2.5 12h2M19.5 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/></svg>'
    : '<svg class="icon" viewBox="0 0 24 24"><path d="M20 14.5A8.5 8.5 0 1 1 9.5 4a7 7 0 0 0 10.5 10.5Z"/></svg>';
}
function alternarTema(){
  const atual = document.documentElement.getAttribute('data-theme') === 'dark' ? 'dark' : 'light';
  const novo = atual === 'dark' ? 'light' : 'dark';
  document.documentElement.setAttribute('data-theme', novo);
  try { localStorage.setItem('mepb-tema', novo); } catch(e){}
  document.getElementById('btnTema').innerHTML = iconeTema(novo);
}

/* ------------------------------------------------------------------ Toast */
function mostrarToast(msg){
  const host = document.getElementById('toastHost');
  const el = document.createElement('div');
  el.textContent = msg;
  el.style.cssText = 'position:fixed;left:50%;bottom:1.5rem;transform:translate(-50%,0);background:var(--navy-950);color:#fff;padding:.75rem 1.25rem;border-radius:var(--radius-md);font-size:.875rem;box-shadow:var(--shadow-lg);z-index:200;max-width:90vw;text-align:center;opacity:0;transition:opacity .25s var(--ease)';
  host.appendChild(el);
  requestAnimationFrame(function(){ el.style.opacity = '1'; });
  setTimeout(function(){ el.style.opacity = '0'; setTimeout(function(){ el.remove(); }, 300); }, 2600);
}

/* --------------------------------------------------------- Montagem da página */
/* ------------------------------------------------------------- Montagem */
/* Cada página HTML final chama apenas a função de montagem que lhe diz
   respeito — mas todas começam chamando montarComum(), que cuida do que é
   igual em qualquer página: cabeçalho, menu, rodapé e tema. */
function montarComum(){
  document.getElementById('logoLink').innerHTML = svgLogoComTexto(false);
  document.getElementById('drawerLogo').innerHTML = svgLogo(false);
  document.getElementById('btnTema').innerHTML = iconeTema(document.documentElement.getAttribute('data-theme'));
  document.getElementById('btnDrawer').innerHTML = '<svg class="icon" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16"/></svg>';
  document.getElementById('btnFecharDrawer').innerHTML = '<svg class="icon" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg>';
  document.getElementById('ctaNavPin').innerHTML = ICONES.pin + 'Encontre uma Igreja';
  document.getElementById('rodape').innerHTML = rodapeHTML();
  document.getElementById('rodapeLogo').innerHTML = svgLogoComTexto(true);
  destacarPaginaAtual();
  inicializarNav();
  inicializarReveal();
  inicializarToasts();
  aplicarImagensLocais();
}

/* Destaca no menu (desktop e drawer) o link que aponta pro arquivo atual. */
function destacarPaginaAtual(){
  const arquivo = location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.nav-links a, .drawer-nav a').forEach(function(a){
    const href = a.getAttribute('href') || '';
    const arquivoAlvo = href.split('#')[0] || 'index.html';
    // Links pra "index.html#âncora" não contam como "página atual" — são
    // apenas trechos dentro da Início, não páginas distintas. Só destaca
    // quando o link aponta para um arquivo de página de fato (Missões, TV,
    // Biblioteca, Localizador, Presidentes, Diretoria).
    const ehPaginaPropria = arquivoAlvo === arquivo && arquivoAlvo !== 'index.html';
    if (ehPaginaPropria) a.setAttribute('aria-current', 'page');
    else a.removeAttribute('aria-current');
  });
}

function montarInicio(){
  montarComum();
  document.getElementById('heroPin').innerHTML = ICONES.pin + 'Encontre uma Igreja';
  document.getElementById('heroSobre').innerHTML = 'Conheça a MEPB ' + ICONES.arrow;
  document.getElementById('heroTorch').outerHTML = svgTocha(0.07).replace('<svg ', '<svg class="hero-torch" id="heroTorch" ');

  const numeros = [
    {v:'85+',r:'anos de história',d:'desde 1939'},
    {v:'21',r:'estados',d:'presença nacional'},
    {v:'16',r:'capitais',d:'em todas as regiões'},
    {v:'130+',r:'municípios',d:'igrejas e congregações'},
    {v:'4',r:'continentes',d:'campo missionário'},
  ];
  document.getElementById('numerosLista').innerHTML = numeros.map(function(n){
    const alvo = parseInt(n.v, 10);
    const sufixo = n.v.replace(String(alvo), '');
    return `<li><span class="valor" data-numeric data-contador data-count-to="${alvo}" data-suffix="${sufixo}">0${sufixo}</span><span class="rotulo">${n.r}</span><span class="detalhe">${n.d}</span></li>`;
  }).join('');

  document.getElementById('secaoSobre').innerHTML = secaoSobre();
  document.getElementById('secaoAcesso').innerHTML = secaoAcesso();
  document.getElementById('secaoNoticias').innerHTML = secaoNoticias();
  document.getElementById('secaoAgenda').innerHTML = secaoAgenda();
  document.getElementById('secaoTestemunhos').innerHTML = secaoTestemunhos();
  document.getElementById('secaoDepartamentos').innerHTML = secaoDepartamentos();
  document.getElementById('secaoOracao').innerHTML = secaoOracao();
  document.getElementById('secaoConvite').innerHTML = secaoConvite();
  document.getElementById('cardOracao').innerHTML = formularioOracaoHTML();

  inicializarTestemunhos();
  inicializarFormularioOracao();
  inicializarContadores();
  inicializarParallaxHero();

  const contagem = {};
  IGREJAS.forEach(function(i){ contagem[i.uf] = (contagem[i.uf]||0)+1; });

  // Mapa-prévia: só visual — ao escolher um estado, navega mesmo pra
  // página do Localizador (outro arquivo) já com o filtro aplicado.
  construirMapaBrasil(document.getElementById('mapaPrevia'), {
    contagemPorUF: contagem,
    selecionavel: true,
    aoSelecionar: function(uf){
      const info = document.getElementById('mapaPreviaInfo');
      if (uf) window.location.href = 'localizador.html?uf=' + uf;
      else info.textContent = 'Toque em um estado para ver a presença da MEPB.';
    },
  });
}

