/* ------------------------------------------------------------------ Nav */
function inicializarNav(){
  const nav = document.getElementById('siteNav');
  let solidoAtual = null;
  function aoRolar(){
    // Só a Início tem hero escuro por trás — nas demais páginas a navbar
    // é sempre sólida, independente da posição de rolagem.
    const temHero = !!document.querySelector('.hero');
    const solido = !temHero || window.scrollY > 24;
    nav.classList.toggle('solido', solido);
    // O logo tem cores próprias embutidas no SVG (não CSS), por isso precisa
    // ser redesenhado ao trocar de estado — a mesma lição do modo escuro no
    // protótipo em React: cor fixa em vez de token semântico quebra o contraste.
    if (solido !== solidoAtual){
      solidoAtual = solido;
      document.getElementById('logoLink').innerHTML = svgLogoComTexto(!solido);
    }
  }
  aoRolar();
  window.addEventListener('scroll', aoRolar, { passive: true });

  document.getElementById('btnTema').addEventListener('click', alternarTema);

  const overlay = document.getElementById('drawerOverlay');
  const drawer = document.getElementById('drawer');
  function abrirDrawer(){ overlay.classList.add('aberto'); drawer.classList.add('aberto'); document.body.style.overflow = 'hidden'; document.getElementById('btnDrawer').setAttribute('aria-expanded','true'); }
  function fecharDrawer(){ overlay.classList.remove('aberto'); drawer.classList.remove('aberto'); document.body.style.overflow = ''; document.getElementById('btnDrawer').setAttribute('aria-expanded','false'); }
  document.getElementById('btnDrawer').addEventListener('click', abrirDrawer);
  document.getElementById('btnFecharDrawer').addEventListener('click', fecharDrawer);
  overlay.addEventListener('click', fecharDrawer);
  drawer.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', fecharDrawer); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') fecharDrawer(); });

  // Dropdown "Quem somos" (desktop) — clique para abrir/fechar, não hover,
  // pra funcionar igual com mouse e com toque.
  const toggleDropdown = document.getElementById('navQuemSomos');
  const menuDropdown = document.getElementById('menuQuemSomos');
  if (toggleDropdown && menuDropdown){
    function fecharDropdown(){ menuDropdown.hidden = true; toggleDropdown.setAttribute('aria-expanded','false'); }
    function abrirDropdown(){ menuDropdown.hidden = false; toggleDropdown.setAttribute('aria-expanded','true'); }
    toggleDropdown.addEventListener('click', function(e){
      e.stopPropagation();
      if (menuDropdown.hidden) abrirDropdown(); else fecharDropdown();
    });
    document.addEventListener('click', function(e){
      if (!menuDropdown.hidden && !menuDropdown.contains(e.target) && e.target !== toggleDropdown) fecharDropdown();
    });
    document.addEventListener('keydown', function(e){ if (e.key === 'Escape') fecharDropdown(); });
    menuDropdown.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', fecharDropdown); });
  }

  // Acordeão "Quem somos" dentro do drawer (mobile).
  const toggleAcordeao = document.getElementById('drawerQuemSomosToggle');
  const painelAcordeao = document.getElementById('drawerQuemSomosPainel');
  if (toggleAcordeao && painelAcordeao){
    toggleAcordeao.addEventListener('click', function(){
      const aberto = !painelAcordeao.hidden;
      painelAcordeao.hidden = aberto;
      toggleAcordeao.setAttribute('aria-expanded', String(!aberto));
    });
  }
}

/* --------------------------------------------------------------- Reveal */
function inicializarReveal(){
  const reduzido = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const elementos = document.querySelectorAll('.reveal');
  if (reduzido || typeof IntersectionObserver === 'undefined'){
    elementos.forEach(function(el){ el.classList.add('visible'); });
    return;
  }
  const obs = new IntersectionObserver(function(entradas){
    entradas.forEach(function(en){
      if (en.isIntersecting){ en.target.classList.add('visible'); obs.unobserve(en.target); }
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -60px 0px' });
  elementos.forEach(function(el){ obs.observe(el); });
}

/* ------------------------------------------------------------- Contadores */
function animarContador(el){
  const alvo = parseInt(el.getAttribute('data-count-to'), 10);
  const sufixo = el.getAttribute('data-suffix') || '';
  if (!alvo && alvo !== 0) return;
  const duracao = 1300;
  const inicio = performance.now();
  function passo(agora){
    const p = Math.min(1, (agora - inicio) / duracao);
    const facilitado = 1 - Math.pow(1 - p, 3); // ease-out cúbico
    el.textContent = Math.round(facilitado * alvo) + sufixo;
    if (p < 1){ requestAnimationFrame(passo); }
    else { el.textContent = alvo + sufixo; el.classList.add('contado'); }
  }
  requestAnimationFrame(passo);
}
function inicializarContadores(){
  const elementos = document.querySelectorAll('[data-contador]');
  const reduzido = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (!elementos.length) return;
  if (reduzido || typeof IntersectionObserver === 'undefined'){
    elementos.forEach(function(el){ el.textContent = el.getAttribute('data-count-to') + (el.getAttribute('data-suffix')||''); });
    return;
  }
  const obs = new IntersectionObserver(function(entradas){
    entradas.forEach(function(en){
      if (en.isIntersecting){ animarContador(en.target); obs.unobserve(en.target); }
    });
  }, { threshold: 0.4 });
  elementos.forEach(function(el){ obs.observe(el); });
}

/* --------------------------------------------------------------- Parallax */
/* --------------------------------------------------------- Imagens locais */
/* Qualquer <img data-local="imagens/arquivo.jpg"> tenta carregar o arquivo
   local primeiro; se ele ainda não existir na pasta imagens/, o site cai de
   volta sozinho para a foto de demonstração (Unsplash) que já estava no
   "src" — sem quebrar o layout e sem precisar editar código nenhum quando
   as fotos reais forem chegando. */
function aplicarImagensLocais(){
  document.querySelectorAll('img[data-local]').forEach(function(img){
    if (img.dataset.localAplicado) return;
    img.dataset.localAplicado = '1';
    const local = img.getAttribute('data-local');
    const demo = img.getAttribute('src');
    const testeImg = new Image();
    testeImg.onload = function(){ img.src = local; };
    testeImg.onerror = function(){ img.src = demo; };
    testeImg.src = local;
  });
}

function inicializarParallaxHero(){
  const bg = document.querySelector('.hero-bg-img');
  const hero = document.querySelector('.hero');
  if (!bg || !hero) return;
  const reduzido = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduzido) return;
  let ticando = false;
  function atualizar(){
    ticando = false;
    const altura = hero.offsetHeight;
    const deslocado = window.scrollY;
    if (deslocado > altura) return;
    bg.style.transform = 'translate3d(0,' + (deslocado * 0.18) + 'px,0) scale(1.06)';
  }
  window.addEventListener('scroll', function(){
    if (!ticando){ ticando = true; requestAnimationFrame(atualizar); }
  }, { passive: true });
  atualizar();
}

/* -------------------------------------------------------------- Toasts */
function inicializarToasts(){
  document.querySelectorAll('[data-toast]').forEach(function(el){
    el.addEventListener('click', function(e){
      e.preventDefault();
      mostrarToast(el.getAttribute('data-toast'));
    });
  });
}

/* --------------------------------------------------------- Localizador */
const localizadorApi = { definirUf: function(){} };

function inicializarLocalizador(mapaCompleto){
  const inputBusca = document.getElementById('buscaIgreja');
  const selectUf = document.getElementById('filtroUf');
  const resultadosEl = document.getElementById('resultadosIgrejas');
  const contagemEl = document.getElementById('contagemResultados');
  const filtrosAtivosEl = document.getElementById('filtrosAtivos');
  const chipUf = document.getElementById('chipUf');
  const chipBusca = document.getElementById('chipBusca');

  let estado = { uf: '', busca: '' };

  function render(){
    const filtradas = IGREJAS.filter(function(ig){
      if (estado.uf && ig.uf !== estado.uf) return false;
      return contemTexto(estado.busca, [ig.nome, ig.cidade, ig.bairro, ig.endereco, ig.pastor, NOMES_UF[ig.uf]]);
    });

    resultadosEl.innerHTML = filtradas.length
      ? filtradas.map(cartaoIgreja).join('')
      : '<p style="grid-column:1/-1;text-align:center;padding:3rem 1rem;border:1px dashed var(--border-strong);border-radius:var(--radius-lg);color:var(--fg-muted)">Nenhuma igreja encontrada com esses filtros.</p>';

    contagemEl.textContent = filtradas.length + (filtradas.length === 1 ? ' resultado' : ' resultados');

    const temFiltro = Boolean(estado.uf || estado.busca.trim());
    filtrosAtivosEl.style.display = temFiltro ? 'flex' : 'none';
    if (estado.uf){ chipUf.style.display='inline-flex'; chipUf.textContent = NOMES_UF[estado.uf] + ' ✕'; } else { chipUf.style.display='none'; }
    if (estado.busca.trim()){ chipBusca.style.display='inline-flex'; chipBusca.textContent = '"' + estado.busca.trim() + '" ✕'; } else { chipBusca.style.display='none'; }
  }

  inputBusca.addEventListener('input', function(){ estado.busca = inputBusca.value; render(); });
  selectUf.addEventListener('change', function(){
    estado.uf = selectUf.value;
    mapaCompleto.definirSelecao(estado.uf);
    render();
  });
  chipUf.addEventListener('click', function(){ estado.uf=''; selectUf.value=''; mapaCompleto.definirSelecao(''); render(); });
  chipBusca.addEventListener('click', function(){ estado.busca=''; inputBusca.value=''; render(); });
  document.getElementById('btnLimparFiltros').addEventListener('click', function(){
    estado = { uf:'', busca:'' }; selectUf.value=''; inputBusca.value=''; mapaCompleto.definirSelecao(''); render();
  });

  localizadorApi.definirUf = function(uf){
    estado.uf = uf; selectUf.value = uf; render();
  };

  render();
}

/* --------------------------------------------------------- Form oração */
function inicializarFormularioOracao(){
  const card = document.getElementById('cardOracao');

  function ligar(){
    const form = document.getElementById('formOracao');
    if (!form) return;
    form.addEventListener('submit', function(e){
      e.preventDefault();
      const nome = document.getElementById('orNome').value.trim();
      const email = document.getElementById('orEmail').value.trim();
      const pedido = document.getElementById('orPedido').value.trim();
      const erros = [];
      if (!nome) erros.push('Informe seu nome.');
      if (!email) erros.push('Informe seu e-mail.');
      else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erros.push('Informe um e-mail válido.');
      if (!pedido) erros.push('Escreva seu pedido.');

      const resumo = document.getElementById('resumoErrosOracao');
      if (erros.length){
        resumo.style.display = 'block';
        resumo.innerHTML = '<p style="margin:0;font-weight:700;color:var(--primary)">' + (erros.length===1?'Há 1 campo que precisa da sua atenção:':'Há '+erros.length+' campos que precisam da sua atenção:') + '</p>' +
          '<ul style="margin:.5rem 0 0;padding-left:1.1rem;font-size:.875rem;color:var(--fg-muted)">' + erros.map(function(m){return '<li>'+m+'</li>';}).join('') + '</ul>';
        document.getElementById(!nome?'orNome':!email?'orEmail':'orPedido').focus();
        return;
      }
      card.innerHTML = sucessoOracaoHTML();
      document.getElementById('btnNovoOracao').addEventListener('click', function(){ card.innerHTML = formularioOracaoHTML(); ligar(); });
    });
  }
  ligar();
}

/* ------------------------------------------------------------------- TV MEPB */
function inicializarTV(){
  document.querySelectorAll('.tv-nav').forEach(function(btn){
    btn.addEventListener('click', function(){
      const row = document.getElementById('tvRow' + btn.getAttribute('data-row'));
      const dir = parseInt(btn.getAttribute('data-dir'), 10);
      row.scrollBy({ left: dir * 340, behavior: 'smooth' });
    });
  });
  // Delegação: os resultados da busca criam novos ".tv-card" depois deste
  // ponto, então o clique é ouvido no contêiner pai, não em cada card.
  const areaTV = document.getElementById('tv');
  if (areaTV){
    areaTV.addEventListener('click', function(e){
      const card = e.target.closest('.tv-card');
      if (!card) return;
      const ci = parseInt(card.getAttribute('data-cat'), 10);
      const vi = parseInt(card.getAttribute('data-item'), 10);
      abrirModalTV(TV_CATEGORIAS[ci].itens[vi]);
    });
  }
  const btnDestaque = document.getElementById('tvBtnDestaque');
  if (btnDestaque) btnDestaque.addEventListener('click', function(){ abrirModalTV(TV_CATEGORIAS[0].itens[0]); });

  const busca = document.getElementById('buscaTV');
  const painelCategorias = document.getElementById('tvCategorias');
  const painelResultados = document.getElementById('tvBuscaResultados');
  if (busca){
    busca.addEventListener('input', function(){
      const termo = normalizar(busca.value || '');
      if (!termo){
        painelResultados.style.display = 'none';
        painelCategorias.style.display = '';
        return;
      }
      const achados = [];
      TV_CATEGORIAS.forEach(function(cat, ci){
        cat.itens.forEach(function(v, vi){
          if (normalizar(v.t).indexOf(termo) !== -1 || normalizar(v.p).indexOf(termo) !== -1 || normalizar(v.cat).indexOf(termo) !== -1){
            achados.push(tvCartaoHTML(v, ci, vi, {}));
          }
        });
      });
      painelCategorias.style.display = 'none';
      painelResultados.style.display = '';
      painelResultados.innerHTML = achados.length
        ? `<p style="color:rgb(255 255 255/.6);font-size:.875rem;margin-bottom:1rem">${achados.length} ${achados.length===1?'resultado':'resultados'}</p><div style="display:flex;flex-wrap:wrap;gap:1rem">${achados.join('')}</div>`
        : `<p style="color:rgb(255 255 255/.6);padding:2rem 0">Nenhum vídeo encontrado para "${busca.value}".</p>`;
    });
  }
}
function abrirModalTV(v){
  const host = document.getElementById('tvModalHost');
  host.innerHTML = tvModalHTML(v);
  document.body.style.overflow = 'hidden';
  const overlay = document.getElementById('tvModalOverlay');
  function fechar(){ host.innerHTML = ''; document.body.style.overflow = ''; document.removeEventListener('keydown', aoEsc); }
  function aoEsc(e){ if (e.key === 'Escape') fechar(); }
  overlay.addEventListener('click', function(e){ if (e.target === overlay) fechar(); });
  document.getElementById('tvModalFechar').addEventListener('click', fechar);
  document.getElementById('tvModalPlay').addEventListener('click', function(){ mostrarToast('Simulador local: aqui entraria a reprodução real do vídeo.'); });
  document.addEventListener('keydown', aoEsc);
  document.getElementById('tvModalFechar').focus();
}

/* ----------------------------------------------------------------- Biblioteca */
function inicializarBiblioteca(){
  const grid = document.getElementById('docGrid');
  const vazio = document.getElementById('docVazio');
  const busca = document.getElementById('buscaDoc');
  const tabs = Array.prototype.slice.call(document.querySelectorAll('.doc-tab'));
  let categoriaAtiva = 'Todos';

  function render(){
    const termo = normalizar(busca.value || '');
    const filtrados = DOCUMENTOS.filter(function(d){
      const passaCategoria = categoriaAtiva === 'Todos' || d.cat === categoriaAtiva;
      const passaBusca = !termo || normalizar(d.n).indexOf(termo) !== -1 || normalizar(d.desc).indexOf(termo) !== -1;
      return passaCategoria && passaBusca;
    });
    grid.innerHTML = filtrados.map(cartaoDocumento).join('');
    vazio.style.display = filtrados.length ? 'none' : 'block';
    inicializarReveal();
    inicializarToasts();
  }

  tabs.forEach(function(tab){
    tab.addEventListener('click', function(){
      categoriaAtiva = tab.getAttribute('data-cat');
      tabs.forEach(function(t){ t.classList.toggle('btn-primary', t === tab); t.classList.toggle('btn-outline', t !== tab); });
      render();
    });
  });
  busca.addEventListener('input', render);
  render();
}

/* --------------------------------------------------------------- Testemunhos */
function inicializarTestemunhos(){
  const host = document.getElementById('testDepo');
  const dots = document.getElementById('testDots');
  let atual = 0, timer = null;

  function render(){
    host.innerHTML = depoimentoHTML(TESTEMUNHOS[atual]);
    aplicarImagensLocais();
    dots.innerHTML = TESTEMUNHOS.map(function(_, i){
      return `<button type="button" aria-label="Ver testemunho ${i+1}" data-i="${i}" style="width:.55rem;height:.55rem;border-radius:99px;border:none;padding:0;background:${i===atual?'var(--primary)':'var(--border-strong)'};cursor:pointer;transition:background .2s"></button>`;
    }).join('');
    dots.querySelectorAll('button').forEach(function(b){
      b.addEventListener('click', function(){ atual = parseInt(b.getAttribute('data-i'), 10); render(); reiniciarAuto(); });
    });
  }
  function avancar(){ atual = (atual + 1) % TESTEMUNHOS.length; render(); }
  function reiniciarAuto(){
    if (timer) clearInterval(timer);
    const reduzido = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (!reduzido) timer = setInterval(avancar, 6000);
  }
  render();
  reiniciarAuto();
}

/* Sobe a página certa quando o documento estiver pronto. Cada arquivo .html
   define window.PAGINA_ATUAL antes de carregar este script. */
function montarPaginaAtual(){
  const pagina = window.PAGINA_ATUAL || 'inicio';
  const funcoes = {
    inicio: montarInicio, missoes: montarMissoes, tv: montarTV,
    biblioteca: montarBiblioteca, localizador: montarLocalizador,
    presidentes: montarPresidentes, diretoria: montarDiretoria,
  };
  (funcoes[pagina] || montarInicio)();
}
if (document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', montarPaginaAtual);
} else {
  montarPaginaAtual();
}
